// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount) public {
        // widen the domain: any positive amount within sane bounds
        amount = bound(amount, 1, 1 ether);

        // adversarial-counterparty avoidance: use an accepting receiver so transfers always succeed
        Receiver r = new Receiver();

        // fund the contract with EXACTLY the requested amount: the reference can pay it, the mutant cannot
        vm.deal(address(c), amount);

        // owner is the deployer of c, i.e. this test contract
        vm.prank(address(this));
        bool ok;
        try c.sendTo(address(r), amount) { ok = true; } catch { ok = false; }

        // Rule: a well-formed sendTo (owner, amount>0, funded contract, accepting receiver)
        // must SUCCEED when c holds exactly `amount`. The mutant tries to send amount+1,
        // so it always reverts in this scenario and violates the rule.
        assertTrue(ok);
    }
}

contract Receiver {
    receive() external payable {}
}
